internal static class ImportQuality
{
    // Purchased CAD is an assembly reference, and can legitimately include
    // surface bodies. Keep its supplied geometry, exposing quality issues.
    // Fabricated parts generated by us must remain valid solid B-reps.
    public static string? Warning(string? origin, int? result, int faults, int solids, int surfaces)
    {
        if (result < 0 || solids == 0 || origin != "library" && (faults > 0 || surfaces > 0))
            throw new InvalidDataException($"Диагностика импортирования: код {result}, дефектов {faults}, твёрдых тел {solids}, поверхностных тел {surfaces}. Требуется исправление исходной геометрии.");
        if (faults > 0)
            return $"Покупная CAD-модель сохранена для компоновки: твёрдых тел {solids}, поверхностных тел {surfaces}, замечаний геометрии {faults}. Геометрия исходника требует исправления перед использованием для изготовления или анализа прочности.";
        return surfaces > 0
            ? $"В покупной CAD-модели сохранены твёрдые тела ({solids}) и поверхности исходника ({surfaces}); ошибок геометрии не выявлено."
            : null;
    }
}
